UPDATE tbl_asset_snapshot
SET ai_analysis_status = 'FAILED',
    ai_analysis_failed_at = CURRENT_TIMESTAMP,
    ai_analysis_completed_at = NULL,
    ai_analysis_failure_code = #{failureCode}
WHERE user_id = #{userId}
  AND `year_month` = #{yearMonth}
  AND ai_analysis_status = 'IN_PROGRESS'
